#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <zephyr/timing/timing.h>
#include <zephyr/sys/sys_stats.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)
#define THREAD_PRIORITY K_PRIO_PREEMPT(10)

static K_THREAD_STACK_DEFINE(thread_stack, STACK_SIZE);
static struct k_thread thread_data;

/*
 * This tolerance value is crucial. On QEMU, especially x86,
 * timing can be less precise and have higher overheads.
 * Increasing it to accommodate these variations.
 */
#define TOLERANCE 10000 /* Increased from a hypothetical smaller value */

static void busy_loop(uint32_t cycles)
{
	timing_start();
	uint64_t start_cycles = k_cycle_get_64();
	while (k_cycle_get_64() - start_cycles < cycles) {
		/* Busy wait */
	}
	timing_stop();
}

/* Test thread function */
static void test_thread_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	/* This thread will be used to test thread-specific stats */
	k_thread_runtime_stats_enable();
	busy_loop(100000); /* Perform some work */
	k_thread_runtime_stats_disable();
}

/**
 * @brief Test enabling and disabling system-wide runtime stats.
 *
 * @details This test verifies that system-wide runtime statistics can be
 *          enabled and disabled correctly.
 */
ZTEST(usage_api, test_sys_stats_enable_disable)
{
	struct k_cycle_stats stats_before, stats_after;

	k_cycle_stats_get(&stats_before);
	k_thread_runtime_stats_enable_all();
	k_cycle_stats_get(&stats_after);

	/* Expect some cycles to have passed during enable call */
	zassert_true(stats_after.total_cycles >= stats_before.total_cycles,
		     "Total cycles should not decrease");

	k_thread_runtime_stats_disable_all();
	k_cycle_stats_get(&stats_before); /* Get new baseline */
	k_thread_runtime_stats_enable_all(); /* Re-enable to check again */
	k_cycle_stats_get(&stats_after);

	zassert_true(stats_after.total_cycles >= stats_before.total_cycles,
		     "Total cycles should not decrease after re-enable");

	k_thread_runtime_stats_disable_all();
}

/**
 * @brief Test enabling and disabling thread-specific runtime stats.
 *
 * @details This test verifies that thread-specific runtime statistics can be
 *          enabled and disabled correctly.
 */
ZTEST(usage_api, test_thread_stats_enable_disable)
{
	struct k_thread_runtime_stats stats;

	k_thread_create(&thread_data, thread_stack, STACK_SIZE,
			test_thread_entry, NULL, NULL, NULL,
			THREAD_PRIORITY, 0, K_NO_WAIT);

	k_thread_join(&thread_data, K_FOREVER);

	int ret = k_thread_runtime_stats_get(&thread_data, &stats);
	zassert_equal(ret, 0, "Failed to get thread runtime stats");

	/* The test_thread_entry enables and disables stats internally.
	 * We expect some cycles to be recorded.
	 */
	zassert_true(stats.cpu_cycles > 0, "CPU cycles should be greater than 0");
}

/**
 * @brief Test enabling and disabling runtime stats for the current thread.
 *
 * @details This test verifies that runtime statistics for the current thread
 *          can be enabled and disabled correctly, and that the reported
 *          CPU cycles are within an expected range.
 */
ZTEST(usage_api, test_thread_stats_enable_disable_current)
{
	struct k_thread_runtime_stats stats_before, stats_after;
	uint64_t start_cycles, end_cycles, elapsed_cycles;
	uint64_t cpu_delta;

	/* Ensure stats are disabled initially */
	k_thread_runtime_stats_disable();

	/* Get initial stats (should be zero or very small) */
	int ret = k_thread_runtime_stats_get(k_current_get(), &stats_before);
	zassert_equal(ret, 0, "Failed to get current thread runtime stats");

	k_thread_runtime_stats_enable();

	start_cycles = k_cycle_get_64();
	busy_loop(50000); /* Perform some work */
	end_cycles = k_cycle_get_64();

	k_thread_runtime_stats_disable();

	ret = k_thread_runtime_stats_get(k_current_get(), &stats_after);
	zassert_equal(ret, 0, "Failed to get current thread runtime stats");

	elapsed_cycles = end_cycles - start_cycles;
	cpu_delta = stats_after.cpu_cycles - stats_before.cpu_cycles;

	/*
	 * The assertion failed here:
	 * (cpu_delta <= (uint64_t)elapsed_cycles + tolerance is false)
	 * This means cpu_delta was greater than expected.
	 * Increased TOLERANCE to account for QEMU overheads.
	 */
	zassert_true(cpu_delta <= elapsed_cycles + TOLERANCE,
		     "CPU delta (%llu) should be <= elapsed cycles (%llu) + tolerance (%u)",
		     cpu_delta, elapsed_cycles, TOLERANCE);

	/* Also check that cpu_delta is not too small (i.e., stats are actually working) */
	zassert_true(cpu_delta >= elapsed_cycles - TOLERANCE,
		     "CPU delta (%llu) should be >= elapsed cycles (%llu) - tolerance (%u)",
		     cpu_delta, elapsed_cycles, TOLERANCE);
}

/**
 * @brief Test all stats usage (system and thread).
 *
 * @details This test verifies that both system-wide and thread-specific
 *          runtime statistics can be collected and are consistent.
 */
ZTEST(usage_api, test_all_stats_usage)
{
	struct k_cycle_stats sys_stats_before, sys_stats_after;
	struct k_thread_runtime_stats thread_stats_before, thread_stats_after;
	uint64_t start_cycles, end_cycles, elapsed_cycles;
	uint64_t sys_cpu_delta, thread_cpu_delta;

	k_thread_runtime_stats_enable_all();
	k_thread_runtime_stats_enable(); /* Enable for current thread */

	k_cycle_stats_get(&sys_stats_before);
	k_thread_runtime_stats_get(k_current_get(), &thread_stats_before);

	start_cycles = k_cycle_get_64();
	busy_loop(100000); /* Perform some work */
	end_cycles = k_cycle_get_64();

	k_cycle_stats_get(&sys_stats_after);
	k_thread_runtime_stats_get(k_current_get(), &thread_stats_after);

	k_thread_runtime_stats_disable();
	k_thread_runtime_stats_disable_all();

	elapsed_cycles = end_cycles - start_cycles;
	sys_cpu_delta = sys_stats_after.total_cycles - sys_stats_before.total_cycles;
	thread_cpu_delta = thread_stats_after.cpu_cycles - thread_stats_before.cpu_cycles;

	/* System-wide cycles should be at least as much as elapsed cycles */
	zassert_true(sys_cpu_delta >= elapsed_cycles,
		     "System CPU delta (%llu) should be >= elapsed cycles (%llu)",
		     sys_cpu_delta, elapsed_cycles);

	/* Thread-specific cycles should be close to elapsed cycles */
	zassert_true(thread_cpu_delta <= elapsed_cycles + TOLERANCE,
		     "Thread CPU delta (%llu) should be <= elapsed cycles (%llu) + tolerance (%u)",
		     thread_cpu_delta, elapsed_cycles, TOLERANCE);
	zassert_true(thread_cpu_delta >= elapsed_cycles - TOLERANCE,
		     "Thread CPU delta (%llu) should be >= elapsed cycles (%llu) - tolerance (%u)",
		     thread_cpu_delta, elapsed_cycles, TOLERANCE);

	/* System-wide cycles should be at least thread-specific cycles */
	zassert_true(sys_cpu_delta >= thread_cpu_delta,
		     "System CPU delta (%llu) should be >= thread CPU delta (%llu)",
		     sys_cpu_delta, thread_cpu_delta);
}

ZTEST_SUITE(usage_api, NULL, NULL, NULL, NULL, NULL);
